<?php
/** Prompt engineering basics: clear requests, context, examples, output format and iterating. */

return [
    'id' => 'prompt-base', 'family' => 'prompt', 'after' => null,
    'title' => L('Prompt engineering base', 'Prompt Engineering Basics'), 'short' => L('Prompt base', 'Prompt Basics'), 'level' => L('Base', 'Basics'),
    'desc' => L('Scrivere richieste che funzionano: chiarezza, contesto, ruolo, esempi, formato della risposta e miglioramento passo per passo.', 'Writing requests that work: clarity, context, role, examples, answer format and step-by-step improvement.'),
    'lessons' => [
        lesson('clear', L('Chiaro e specifico', 'Clear and specific'), [
            P('Un **prompt** è il testo che dai al modello. Il modello non legge nel pensiero: più sei **specifico** su compito, pubblico, lunghezza e tono, migliore è la risposta. Immagina di dare istruzioni a un collega bravissimo appena arrivato, che non sa nulla del tuo progetto.', 'A **prompt** is the text you give the model. The model cannot read your mind: the more **specific** you are about task, audience, length and tone, the better the answer. Picture briefing a brilliant colleague who just joined and knows nothing about your project.'),
            C('✗  Scrivi qualcosa sul caffè.
✓  Scrivi 3 frasi per la pagina “Chi siamo” di una torrefazione di Trieste,
   tono caldo e familiare, rivolto a turisti, senza superlativi.', 'text'),
            P('Usa verbi d’azione (“riassumi”, “elenca”, “riscrivi”), indica i vincoli e dì cosa fare, non solo cosa evitare.', 'Use action verbs (“summarise”, “list”, “rewrite”), state the constraints and say what to do, not only what to avoid.'),
        ], [
            Q('c1', L('Che cosa rende migliore un prompt?', 'What makes a prompt better?'), [L('Compito, pubblico e vincoli precisi', 'Precise task, audience and constraints'), L('Essere il più breve possibile', 'Being as short as possible'), L('Usare tante emoji', 'Using lots of emoji'), L('Scrivere tutto in maiuscolo', 'Writing everything in capitals')], 0, L('Il modello non indovina quello che non dici.', 'The model cannot guess what you do not say.')),
            Q('c2', L('Qual è il prompt più specifico?', 'Which prompt is the most specific?'), [L('Riassumi questo articolo in 5 punti per un manager', 'Summarise this article in 5 bullet points for a manager'), L('Parlami di questo', 'Tell me about this'), L('Fai qualcosa di bello', 'Do something nice'), L('Articolo', 'Article')], 0, L('Compito, formato e pubblico.', 'Task, format and audience.')),
            Q('c3', L('Meglio dire “non essere prolisso” o…', 'Better to say “don’t be verbose” or…'), [L('“Rispondi in massimo 3 frasi”', '“Answer in at most 3 sentences”'), L('“Niente”', '“Nothing”'), L('“Sii come vuoi”', '“Be however you like”'), L('“Scrivi tanto”', '“Write a lot”')], 0, L('Dire cosa fare è più chiaro.', 'Saying what to do is clearer.')),
        ], task('text', L('Migliora il prompt “Scrivi una mail” indicando: il **destinatario**, lo **scopo** e una **lunghezza** in parole o frasi.', 'Improve the prompt “Write an email” by stating: the **recipient**, the **purpose** and a **length** in words or sentences.'), 'Scrivi una mail', [re('mail|email', L('È ancora una mail', 'It is still an email')), re('\b(a|al|alla|ai|to|per)\s+\w+', L('C’è un destinatario', 'There is a recipient')), re('\d+\s*(parole|frasi|righe|words|sentences|lines)', L('C’è una lunghezza', 'There is a length')), re('per (chiedere|ringraziare|annunciare|invitare|confermare|spiegare)|to (ask|thank|announce|invite|confirm|explain)', L('C’è uno scopo', 'There is a purpose'))], '', 'Scrivi una mail al mio responsabile per chiedere un giorno di ferie venerdì, tono cortese, massimo 80 parole.'), [
            dMatch(pMatch(), [[L('Compito', 'Task'), L('Riassumi, elenca, riscrivi', 'Summarise, list, rewrite')], [L('Pubblico', 'Audience'), L('Per chi è', 'Who it is for')], [L('Vincolo', 'Constraint'), L('Massimo 100 parole', 'At most 100 words')], [L('Tono', 'Tone'), L('Formale o amichevole', 'Formal or friendly')]], L('Gli ingredienti di un prompt chiaro.', 'The ingredients of a clear prompt.')),
            dFlash(pFlash(), [[L('Il modello sa già il contesto del tuo progetto', 'The model already knows your project’s context'), false], [L('Indicare la lunghezza aiuta', 'Stating the length helps'), true], [L('“Fai qualcosa di bello” è un prompt specifico', '“Do something nice” is a specific prompt'), false], [L('È meglio dire cosa fare che solo cosa evitare', 'Better to say what to do than only what to avoid'), true]], L('Specifico batte vago.', 'Specific beats vague.')),
        ]),
        lesson('context', L('Contesto e ruolo', 'Context and role'), [
            P('Il **contesto** è tutto quello che il modello deve sapere: a chi serve il risultato, perché, cosa è già stato fatto. Dare il **perché** di un vincolo aiuta: “risposte brevi, perché verranno lette ad alta voce” funziona meglio di “risposte brevi”.', '**Context** is everything the model needs to know: who the result is for, why, what has already been done. Giving the **why** behind a constraint helps: “short answers, because they will be read aloud” works better than “short answers”.'),
            C('Sei un insegnante di matematica delle medie.
Contesto: i miei studenti (12 anni) confondono area e perimetro.
Compito: spiega la differenza con un esempio sul giardino di casa.
Formato: massimo 6 righe, niente formule complicate.', 'text'),
            P('Assegnare un **ruolo** (“sei un revisore legale”, “sei un tutor paziente”) orienta lessico e livello. Separa le parti del prompt con titoli o tag come `<documento>…</documento>` quando incolli testi lunghi.', 'Assigning a **role** (“you are a legal reviewer”, “you are a patient tutor”) steers vocabulary and level. Separate the parts of the prompt with headings or tags like `<document>…</document>` when you paste long text.'),
        ], [
            Q('x1', L('Perché spiegare il motivo di un vincolo?', 'Why explain the reason for a constraint?'), [L('Il modello lo applica in modo più sensato', 'The model applies it more sensibly'), L('Per allungare il prompt', 'To make the prompt longer'), L('È obbligatorio', 'It is mandatory'), L('Per confondere il modello', 'To confuse the model')], 0, L('Capisce lo scopo, non solo la regola.', 'It grasps the goal, not just the rule.')),
            Q('x2', L('A che cosa serve assegnare un ruolo?', 'What is assigning a role for?'), [L('Orientare stile e livello', 'Steering style and level'), L('Dare accesso a internet', 'Giving internet access'), L('Rendere il modello più veloce', 'Making the model faster'), L('Cambiare lingua', 'Changing language')], 0, L('Un tutor parla diverso da un avvocato.', 'A tutor speaks differently from a lawyer.')),
            Q('x3', L('Come separi un documento lungo dalle istruzioni?', 'How do you separate a long document from the instructions?'), [L('Con tag come `<documento>`', 'With tags like `<document>`'), L('Non si separa', 'You do not'), L('Con tante righe vuote', 'With many blank lines'), L('Scrivendo in rosso', 'Writing in red')], 0, L('Così il modello sa cosa è cosa.', 'So the model knows what is what.')),
        ], task('text', L('Scrivi un prompt con tre righe che iniziano con `Ruolo:`, `Contesto:` e `Compito:` per farti aiutare a preparare un colloquio di lavoro.', 'Write a prompt with three lines starting with `Role:`, `Context:` and `Task:` to get help preparing for a job interview.'), "Ruolo: \nContesto: \nCompito: ", [re('^(Ruolo|Role):\s*\S.{3,}', L('C’è il ruolo', 'There is the role')), re('^(Contesto|Context):\s*\S.{3,}', L('C’è il contesto', 'There is the context')), re('^(Compito|Task):\s*\S.{3,}', L('C’è il compito', 'There is the task')), re('colloquio|interview', L('Parla del colloquio', 'It is about the interview'))], '', "Ruolo: sei un selezionatore esperto nel settore software.\nContesto: ho un colloquio da sviluppatore junior giovedì, è il mio primo.\nCompito: fammi 5 domande tipiche una alla volta e commenta le mie risposte."), [
            dOrder(pSort(), [L('Ruolo: sei un tutor di inglese', 'Role: you are an English tutor'), L('Contesto: ho un esame B2 tra un mese', 'Context: I have a B2 exam in a month'), L('Compito: correggi il mio testo', 'Task: correct my text'), L('Formato: elenco degli errori con spiegazione', 'Format: list of mistakes with explanation')], L('Chi sei, la situazione, cosa fare, come.', 'Who you are, the situation, what to do, how.')),
            dBlanks(pFill(), "Riassumi il testo qui sotto in 3 punti.\n<___>\n…testo incollato…\n</___>", ['documento', 'documento'], ['fine', 'inizio'], L('Tag di apertura e chiusura uguali.', 'Matching opening and closing tags.')),
        ]),
        lesson('examples', L('Esempi: few-shot', 'Examples: few-shot'), [
            P('Mostrare **esempi** è uno dei modi più potenti per ottenere il formato e lo stile che vuoi. Senza esempi si parla di **zero-shot**; con uno **one-shot**; con alcuni **few-shot**.', 'Showing **examples** is one of the most powerful ways to get the format and style you want. Without examples it is **zero-shot**; with one **one-shot**; with a few **few-shot**.'),
            C('Classifica il sentimento della recensione.
Recensione: “Spedizione velocissima, prodotto perfetto.” → positivo
Recensione: “Arrivato rotto, nessuna risposta.” → negativo
Recensione: “Buono, ma la batteria dura poco.” →', 'text'),
            P('Gli esempi devono essere **vari** e rappresentativi: se sono tutti uguali, il modello copierà dettagli che non volevi (stessa lunghezza, stesse parole).', 'Examples must be **varied** and representative: if they are all alike, the model copies details you did not want (same length, same words).'),
        ], [
            Q('e1', L('Che cos’è un prompt few-shot?', 'What is a few-shot prompt?'), [L('Un prompt con alcuni esempi', 'A prompt with a few examples'), L('Un prompt molto breve', 'A very short prompt'), L('Un prompt senza istruzioni', 'A prompt with no instructions'), L('Un prompt in più lingue', 'A prompt in several languages')], 0, L('Zero, uno o pochi esempi.', 'Zero, one or a few examples.')),
            Q('e2', L('Perché gli esempi devono essere vari?', 'Why must examples be varied?'), [L('Per non far copiare dettagli indesiderati', 'So unwanted details are not copied'), L('Per allungare la risposta', 'To lengthen the answer'), L('Perché il modello si annoia', 'Because the model gets bored'), L('Non serve', 'It does not matter')], 0, L('Il modello imita tutto quello che vede.', 'The model imitates everything it sees.')),
            Q('e3', L('Un prompt senza esempi è…', 'A prompt with no examples is…'), ['zero-shot', 'one-shot', 'few-shot', 'multi-shot'], 0, L('Solo istruzioni.', 'Only instructions.')),
        ], task('text', L('Scrivi un prompt few-shot che trasformi un nome di città nella sua regione, con almeno **2 esempi** nel formato `Città → Regione` e poi `Udine →` da completare.', 'Write a few-shot prompt that turns a city into its region, with at least **2 examples** in the format `City → Region` and then `Udine →` to complete.'), '', [re('(^|\n)\s*\w[^\n→]*→\s*\w+[^\n]*\n\s*\w[^\n→]*→\s*\w+', L('Almeno due esempi completi', 'At least two complete examples')), re('Udine\s*→\s*$', L('Finisce con Udine da completare', 'It ends with Udine to complete'))], '', "Indica la regione della città.\nTorino → Piemonte\nBari → Puglia\nUdine →"), [
            dMatch(pMatch(), [['Zero-shot', L('Nessun esempio', 'No examples')], ['One-shot', L('Un esempio', 'One example')], ['Few-shot', L('Alcuni esempi', 'A few examples')], [L('Esempi vari', 'Varied examples'), L('Evitano imitazioni sbagliate', 'Avoid wrong imitation')]], L('Quanti esempi dare.', 'How many examples to give.')),
            dFlash(pFlash(), [[L('Gli esempi aiutano a fissare il formato', 'Examples help fix the format'), true], [L('Più esempi identici sono sempre meglio', 'More identical examples are always better'), false], [L('Few-shot vuol dire pochi esempi', 'Few-shot means a few examples'), true], [L('Gli esempi non influenzano mai lo stile', 'Examples never influence style'), false]], L('Mostra, non solo dire.', 'Show, don’t just tell.')),
        ]),
        lesson('format', L('Il formato della risposta', 'The answer format'), [
            P('Chiedi esplicitamente il **formato**: elenco puntato, tabella, JSON, numero di paragrafi, lingua. Se il risultato finirà in un programma, chiedi un formato che si possa leggere con il codice, come il **JSON**, e descrivi i campi.', 'Ask explicitly for the **format**: bullet list, table, JSON, number of paragraphs, language. If the result will feed a program, ask for a format code can read, like **JSON**, and describe the fields.'),
            C('Estrai i dati dalla mail e rispondi solo con JSON:
{"nome": string, "data": "AAAA-MM-GG", "partecipanti": numero}', 'text'),
            P('Puoi anche chiedere al modello di pensare prima di rispondere (“ragiona passo per passo, poi dai la risposta finale”): aiuta nei problemi con più passaggi.', 'You can also ask the model to think before answering (“reason step by step, then give the final answer”): it helps with multi-step problems.'),
        ], [
            Q('f1', L('Quale formato è più comodo da leggere con il codice?', 'Which format is easiest to read with code?'), ['JSON', L('Un tema libero', 'A free essay'), L('Una poesia', 'A poem'), L('Un elenco disordinato', 'A messy list')], 0, L('Ha una struttura precisa.', 'It has a precise structure.')),
            Q('f2', L('Perché descrivere i campi del JSON?', 'Why describe the JSON fields?'), [L('Così il modello usa nomi e tipi giusti', 'So the model uses the right names and types'), L('Per abbellire il prompt', 'To decorate the prompt'), L('Non serve mai', 'It is never needed'), L('Per renderlo più lento', 'To make it slower')], 0, L('Il programma si aspetta quei campi.', 'The program expects those fields.')),
            Q('f3', L('Quando aiuta “ragiona passo per passo”?', 'When does “reason step by step” help?'), [L('Nei problemi con più passaggi', 'In multi-step problems'), L('Per salutare', 'For greetings'), L('Mai', 'Never'), L('Solo con le immagini', 'Only with images')], 0, L('Spezza il problema.', 'It breaks the problem down.')),
        ], task('text', L('Scrivi un prompt che chieda di estrarre da una ricevuta `negozio`, `totale` e `data`, rispondendo **solo con JSON**.', 'Write a prompt asking to extract `negozio` (shop), `totale` (total) and `data` (date) from a receipt, answering **only with JSON**.'), '', [re('JSON', L('Chiedi JSON', 'You ask for JSON')), re('negozio', L('Campo negozio', 'Shop field')), re('totale', L('Campo totale', 'Total field')), re('"?data"?', L('Campo data', 'Date field')), re('solo|only', L('Solo JSON, niente altro', 'Only JSON, nothing else'))], '', 'Dalla ricevuta qui sotto estrai negozio, totale e data. Rispondi solo con JSON: {"negozio": string, "totale": numero, "data": "AAAA-MM-GG"}'), [
            dBlanks(pFill(), "Rispondi solo con ___:\n{\"titolo\": string, \"voto\": ___}", ['JSON', 'numero'], ['HTML', 'colore'], L('Formato e tipo del campo.', 'Format and field type.')),
            dMatch(pMatch(), [[L('Elenco puntato', 'Bullet list'), L('Punti brevi', 'Short points')], [L('Tabella', 'Table'), L('Confronti in colonne', 'Comparisons in columns')], ['JSON', L('Dati per un programma', 'Data for a program')], [L('Passo per passo', 'Step by step'), L('Problemi a più passaggi', 'Multi-step problems')]], L('Il formato giusto per lo scopo.', 'The right format for the goal.')),
        ]),
        lesson('iterate', L('Migliorare per tentativi', 'Improving by iteration'), [
            P('Il primo prompt raramente è quello buono. Si lavora a **cicli**: provi, guardi cosa non va, correggi una cosa alla volta. Nelle chat puoi anche dare **feedback** (“più breve”, “togli il gergo”, “il secondo punto è sbagliato perché…”).', 'The first prompt is rarely the good one. You work in **loops**: try, see what is off, fix one thing at a time. In chats you can also give **feedback** (“shorter”, “drop the jargon”, “the second point is wrong because…”).'),
            P('Per compiti grandi, **spezza** in passaggi: prima la scaletta, poi ogni sezione, poi la revisione. Salva i prompt che funzionano e riusali come modelli.', 'For big tasks, **split** into steps: first the outline, then each section, then the review. Save the prompts that work and reuse them as templates.'),
            Tip('Se una risposta è sbagliata, spesso conviene correggere il prompt e ricominciare invece di discutere per dieci messaggi.', 'If an answer is wrong, it is often better to fix the prompt and start over than to argue for ten messages.'),
        ], [
            Q('i1', L('Come si migliora un prompt?', 'How do you improve a prompt?'), [L('Provando e correggendo una cosa alla volta', 'Trying and fixing one thing at a time'), L('Cambiando tutto ogni volta', 'Changing everything each time'), L('Ripetendo la stessa richiesta', 'Repeating the same request'), L('Scrivendo più forte', 'Writing louder')], 0, L('Così capisci cosa ha funzionato.', 'That way you know what worked.')),
            Q('i2', L('Come affronti un compito molto grande?', 'How do you tackle a very large task?'), [L('Lo spezzi in passaggi', 'Split it into steps'), L('Lo chiedi tutto in una riga', 'Ask for it all in one line'), L('Lasci perdere', 'Give up'), L('Lo chiedi in un’altra lingua', 'Ask in another language')], 0, L('Scaletta, sezioni, revisione.', 'Outline, sections, review.')),
            Q('i3', L('Che cosa conviene fare con un prompt che funziona?', 'What should you do with a prompt that works?'), [L('Salvarlo come modello', 'Save it as a template'), L('Cancellarlo', 'Delete it'), L('Non usarlo più', 'Never use it again'), L('Renderlo più vago', 'Make it vaguer')], 0, L('Riusarlo fa risparmiare tempo.', 'Reusing it saves time.')),
        ], task('text', L('Scrivi tre righe di feedback per migliorare una risposta troppo lunga e tecnica: una che inizia con `1.`, una con `2.`, una con `3.`.', 'Write three lines of feedback to improve an answer that is too long and technical: one starting with `1.`, one with `2.`, one with `3.`.'), "1. \n2. \n3. ", [re('^1\.\s*\S.{3,}', L('Primo feedback', 'First feedback')), re('^2\.\s*\S.{3,}', L('Secondo feedback', 'Second feedback')), re('^3\.\s*\S.{3,}', L('Terzo feedback', 'Third feedback')), re('brev|cort|short|meno|fewer|\d+\s*(parole|frasi|words|sentences)', L('Chiedi di accorciare', 'You ask to shorten'))], '', "1. Accorcia a massimo 5 frasi.\n2. Togli il gergo tecnico o spiegalo.\n3. Aggiungi un esempio concreto alla fine."), [
            dOrder(pSort(), [L('Scrivi il primo prompt', 'Write the first prompt'), L('Leggi la risposta', 'Read the answer'), L('Trova cosa non va', 'Find what is off'), L('Correggi una cosa', 'Fix one thing'), L('Riprova', 'Try again')], L('Il ciclo del prompt.', 'The prompt loop.')),
            dFlash(pFlash(), [[L('Il primo prompt è quasi sempre perfetto', 'The first prompt is almost always perfect'), false], [L('Spezzare un compito grande aiuta', 'Splitting a big task helps'), true], [L('Il feedback in chat può migliorare la risposta', 'Feedback in chat can improve the answer'), true], [L('Conviene cambiare tutto a ogni tentativo', 'Better to change everything on each attempt'), false]], L('Piccoli passi, risultati migliori.', 'Small steps, better results.')),
        ]),
    ],
];
